query:
SELECT COUNT(*) as total_offers FROM referralOffers;
SELECT COUNT(*) as sample_offers FROM referralOffers WHERE isSample = 1;
SELECT b.region, COUNT(ro.id) as offer_count FROM referralOffers ro JOIN businesses b ON ro.businessId = b.id GROUP BY b.region ORDER BY offer_count DESC;

